import re
s = open('eprint/Fig11.eps').read()
# tokenize the whole drawing stream after prolog
body = s[s.index('%%EndProlog'):]
toks = body.replace('\n',' ').split()

paths = []
cur = None
color = (0,0,0)
i = 0
x=y=0
while i < len(toks):
    t = toks[i]
    def num(k): return float(toks[k])
    if t == 'c' and i>=3:
        try: color = (float(toks[i-3]), float(toks[i-2]), float(toks[i-1]))
        except: pass
    elif t == 'm' and i>=2:
        try:
            x,y = num(i-2), num(i-1)
            cur = [(x,y)]
        except: pass
    elif t == 'l' and i>=2 and cur is not None:
        x,y = num(i-2), num(i-1); cur.append((x,y))
    elif t == 'd' and i>=2 and cur is not None:
        try:
            dx,dy = num(i-2), num(i-1); x+=dx; y+=dy; cur.append((x,y))
        except: pass
    elif t == 'X' and i>=1 and cur is not None:
        try:
            x += num(i-1); cur.append((x,y))
        except: pass
    elif t == 'Y' and i>=1 and cur is not None:
        try:
            y += num(i-1); cur.append((x,y))
        except: pass
    elif t == 'f' and cur is not None:
        paths.append((color, list(cur)))
        cur = None
    elif t == 's':
        cur = None
    i += 1

for col, p in paths:
    xs = [q[0] for q in p]; ys=[q[1] for q in p]
    print(col, len(p), 'x:[%.0f,%.0f] y:[%.0f,%.0f]' % (min(xs),max(xs),min(ys),max(ys)))
